def find_min(numbers):
    min_val = numbers[0]
    for n in numbers:
        if n < min_val:
            min_val = n
    return min_val

nums = [45, 12, 78, 6, 34]
print(find_min(nums))

def filter_greater_than_10(numbers):
    result = []
    for n in numbers:
        if n >= 10:
            result.append(n)
    return result

data = [5, 12, 3, 20, 8, 15]
print(filter_greater_than_10(data))

def contains_value(numbers, target):
    for n in numbers:
        if n == target:
            return True
    return False

scores = [35, 60, 72, 88, 91]
print(contains_value(scores, 72))

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

